import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int T = Integer.parseInt(br.readLine()); while (T-- > 0) { int N = Integer.parseInt(br.readLine()); StringTokenizer st = new StringTokenizer(br.readLine()); Map<String, Integer>[] suffixMasks = new HashMap[26]; for (int i = 0; i < 26; i++) suffixMasks[i] = new HashMap<>(); int[] count = new int[26]; for (int i = 0; i < N; i++) { String s = st.nextToken(); int first = s.charAt(0) - 'a'; String suffix = s.substring(1); count[first]++; suffixMasks[first].put(suffix, 1); } long ans = 0; for (int i = 0; i < 26; i++) { for (int j = i + 1; j < 26; j++) { int common = 0; for (String s : suffixMasks[i].keySet()) { if (suffixMasks[j].containsKey(s)) { common++; } } ans += 2L * (count[i] - common) * (count[j] - common); } } System.out.println(ans); } } }